	@Test
	void payloadAndFramingCostsAreExplicitIncludingTheZeroByteBaseline() {
		int[] payloadBytes = { 0, 2, 3, 4, 4, 16, 32, 128, 512, 128, 512, 4, 24, 32, 128, 512, 128, 32, 128 };
		assertThat(Variant.values()).hasSize(payloadBytes.length);
		for (Variant variant : Variant.values()) {
			assertThat(variant.payloadBytes()).as("%s payload", variant).isEqualTo(payloadBytes[variant.ordinal()]);
			assertThat(variant.headerBytes()).as("%s envelope", variant)
					.isEqualTo(variant == Variant.NONE ? 0 : payloadBytes[variant.ordinal()] + 4);
			assertThat(PageTextPrototypeSummary.build(variant, List.of("label"))).hasSize(variant.headerBytes());
		}
		assertThat(PageTextPrototypeSummary.SELECTED_CHARACTERS).hasSize(32);
		assertThat(PageTextPrototypeSummary.SELECTED_CHARACTERS.chars().distinct().count()).isEqualTo(32);
	}

	@Test
	void characterMasksRejectOnlyMissingTrackedCharacters() {
		for (Variant variant : List.of(Variant.COMMON16, Variant.COMMON24, Variant.COMMON32,
				Variant.SELECTED32, Variant.ASCII128)) {
			byte[] header = PageTextPrototypeSummary.build(variant, List.of("abc"));
			String tracked = variant == Variant.SELECTED32 ? "q" : " ";
			for (Operation operation : Operation.values()) {
				assertThat(probe(header, variant, operation, "abc")).as("%s %s", variant, operation).isTrue();
				assertThat(probe(header, variant, operation, tracked)).as("%s %s", variant, operation).isFalse();
				assertThat(probe(header, variant, operation, "\ud83d\ude00")).isTrue();
			}
			if (variant != Variant.ASCII128) {
				String allTracked = variant == Variant.SELECTED32 ? PageTextPrototypeSummary.SELECTED_CHARACTERS
						: PageTextPrototypeSummary.COMMON_ORDER.substring(0, variant.signatureBits());
				byte[] saturated = PageTextPrototypeSummary.build(variant, List.of(allTracked, "later label"));
				assertThat(PageTextPrototypeSummary.occupiedBits(saturated, variant))
						.isEqualTo(variant.signatureBits());
				for (Operation operation : Operation.values()) {
					assertThat(probe(saturated, variant, operation, allTracked + " absent \ud83d\ude00")).isTrue();
				}
			}
		}
		byte[] ascii = PageTextPrototypeSummary.build(Variant.ASCII128, List.of("\u0000a\u007f"));
		assertThat(probe(ascii, Variant.ASCII128, Operation.CONTAINS, "\u0000\u007f")).isTrue();
		assertThat(probe(ascii, Variant.ASCII128, Operation.CONTAINS, "\u0001")).isFalse();
	}

	@Test
	void gramsNeverCrossLabelBoundariesAndTheExactUnionExposesDistributedFalsePositives() {
		for (Variant variant : List.of(Variant.GRAM256, Variant.GRAM1024, Variant.GRAM4096)) {
			byte[] header = PageTextPrototypeSummary.build(variant, List.of("ab", "c"));
			assertThat(probe(header, variant, Operation.CONTAINS, "abc")).as("%s", variant).isFalse();
			assertThat(probe(header, variant, Operation.CONTAINS, "ab")).isTrue();
			assertThat(probe(header, variant, Operation.CONTAINS, "")).isTrue();
			assertThat(probe(header, variant, Operation.CONTAINS, "\u00e9")).isTrue();
			assertThat(probe(header, variant, Operation.CONTAINS, "\u20ac")).isFalse();
		}
		assertThat(PageTextPrototypeSummary.exactGramMayMatch(List.of("ab", "c"), "abc")).isFalse();
		List<String> distributed = List.of("abc", "bcd");
		assertThat(distributed.stream().anyMatch(label -> label.contains("abcd"))).isFalse();
		assertThat(PageTextPrototypeSummary.exactGramMayMatch(distributed, "abcd")).isTrue();
		assertThat(PageTextPrototypeSummary.exactGramMayMatch(distributed, "bcde")).isFalse();
		for (Variant variant : List.of(Variant.GRAM256, Variant.GRAM1024, Variant.GRAM4096)) {
			assertThat(probe(PageTextPrototypeSummary.build(variant, distributed), variant,
					Operation.CONTAINS, "abcd")).isTrue();
		}
		for (Variant variant : List.of(Variant.FOURGRAM1024, Variant.FOURGRAM4096)) {
			byte[] header = PageTextPrototypeSummary.build(variant, List.of("abc", "d"));
			assertThat(probe(header, variant, Operation.CONTAINS, "abcd")).as("%s", variant).isFalse();
			assertThat(probe(header, variant, Operation.CONTAINS, "abc")).isTrue();
			assertThat(probe(header, variant, Operation.CONTAINS, "\u20ac")).isTrue();
			assertThat(probe(PageTextPrototypeSummary.build(variant, List.of("abcd", "bcde")), variant,
					Operation.CONTAINS, "abcde")).isTrue();
		}
		assertThat(PageTextPrototypeSummary.exactFourGramMayMatch(List.of("abc", "d"), "abcd")).isFalse();
		assertThat(PageTextPrototypeSummary.exactFourGramMayMatch(List.of("abc", "d"), "abc")).isTrue();
		assertThat(PageTextPrototypeSummary.exactFourGramMayMatch(List.of("abcd", "bcde"), "abcde")).isTrue();
		assertThat(PageTextPrototypeSummary.exactFourGramMayMatch(List.of("abcd", "bcde"), "abcdef")).isFalse();
	}

	@Test
	void existingLiteralGramSignaturesCanBeAggregatedWithoutMaterializingLabels() {
		List<String> labels = List.of("", "ALPHA", "\u039f\u03a3", "\u0130I\u0131i", "\u20ac\ud83d\ude00",
				"A\u0000B", "abcdefgh ordinary catalog");
		for (Locale locale : List.of(Locale.ROOT, Locale.forLanguageTag("tr"), Locale.forLanguageTag("lt"))) {
			List<String> normalized = labels.stream().map(label -> label.toLowerCase(locale)).toList();
			List<byte[]> summaries = labels.stream().map(label -> LiteralTextSummary.create(label, locale)).toList();
			assertThat(PageTextPrototypeSummary.buildGram256FromLiteralSummaries(summaries))
					.as("normalization %s", locale)
					.isEqualTo(PageTextPrototypeSummary.build(Variant.GRAM256, normalized));
			byte[] page = PageTextPrototypeSummary.buildGram256FromLiteralSummaries(summaries);
			for (String label : normalized) {
				assertEverySubstringSurvives(page, Variant.GRAM256, label);
			}
		}
	}

	@Test
	void addingLabelsCanOnlyWidenThePageCandidateSet() {
		List<String> first = List.of("alphabet", "\u00e9clair", "");
		List<String> second = List.of("alphabet", "\u00e9clair", "", "zebra", "0123456789", "\ud83d\ude00");
		List<String> needles = List.of("", "al", "alphabet", "phab", "\u00e9", "zeb", "zebra", "987", "absent");
		for (Variant variant : Variant.values()) {
			byte[] before = PageTextPrototypeSummary.build(variant, first);
			byte[] after = PageTextPrototypeSummary.build(variant, second);
			for (Operation operation : Operation.values()) {
				for (String needle : needles) {
					PreparedQuery query = PageTextPrototypeSummary.prepare(variant, operation, needle);
					if (PageTextPrototypeSummary.mayMatch(before, query)) {
						assertThat(PageTextPrototypeSummary.mayMatch(after, query))
								.as("%s %s %s", variant, operation, needle)
								.isTrue();
					}
				}
			}
		}
	}

