	@Test
	void malformedVersionTruncatedAndWrongLayoutHeadersFallBack() {
		for (Variant variant : Variant.values()) {
			PreparedQuery query = PageTextPrototypeSummary.prepare(variant, Operation.EQUALS, "absent needle");
			byte[] header = PageTextPrototypeSummary.build(variant, List.of("abc"));
			assertThat(PageTextPrototypeSummary.mayMatch(null, query)).isTrue();
			assertThat(PageTextPrototypeSummary.mayMatch(header, -1, query)).isTrue();
			assertThat(PageTextPrototypeSummary.mayMatch(header, Integer.MAX_VALUE, query)).isTrue();
			if (variant == Variant.NONE) {
				assertThat(PageTextPrototypeSummary.mayMatch(header, query)).isTrue();
				continue;
			}
			assertThat(PageTextPrototypeSummary.mayMatch(Arrays.copyOf(header, header.length - 1), query)).isTrue();
			for (int byteOffset = 0; byteOffset < PageTextPrototypeSummary.FRAMING_BYTES; byteOffset++) {
				byte[] wrongVersion = header.clone();
				wrongVersion[byteOffset] ^= (byte) (byteOffset == 0 ? 0x20 : 0x80);
				assertThat(PageTextPrototypeSummary.mayMatch(wrongVersion, query)).as("%s %s", variant, byteOffset)
						.isTrue();
			}
			byte[] wrongVariant = header.clone();
			wrongVariant[0] = (byte) ((variant.ordinal() + 1) % Variant.values().length);
			assertThat(PageTextPrototypeSummary.mayMatch(wrongVariant, query)).isTrue();
		}
	}

	@Test
	void offsetProbesReadOnlyTheSummaryAndAcceptUnalignedLocations() {
		for (Variant variant : Variant.values()) {
			byte[] summary = PageTextPrototypeSummary.build(variant, List.of("first needle last", "\u20ac price"));
			byte[] page = new byte[summary.length + 19];
			Arrays.fill(page, (byte) 0xa5);
			System.arraycopy(summary, 0, page, 7, summary.length);
			byte[] original = page.clone();
			for (Operation operation : Operation.values()) {
				for (String needle : List.of("needle", "first", "\u20ac", "unrelated", "")) {
					PreparedQuery query = PageTextPrototypeSummary.prepare(variant, operation, needle);
					assertThat(PageTextPrototypeSummary.mayMatch(page, 7, query))
							.isEqualTo(PageTextPrototypeSummary.mayMatch(summary, query));
				}
			}
			assertThat(page).isEqualTo(original);
		}
	}

	@Test
	void lengthAndUnsignedPrefixIntervalsRespectPaddingAndMultibyteBoundaries() {
		for (String label : List.of("a\u0000b\u0000cdefghi", "\u20ac price", "\ud83d\ude00 smile",
				"abcdefg\ud83d\ude00", "")) {
			byte[] header = PageTextPrototypeSummary.build(Variant.PREFIX_RANGE, List.of(label));
			assertEverySubstringSurvives(header, Variant.PREFIX_RANGE, label);
			assertThat(probe(header, Variant.PREFIX_RANGE, Operation.EQUALS, label)).isTrue();
			assertThat(probe(header, Variant.PREFIX_RANGE, Operation.EQUALS, label + "x")).isFalse();
		}
		byte[] range = PageTextPrototypeSummary.build(Variant.PREFIX_RANGE, List.of("car", "cat"));
		assertThat(probe(range, Variant.PREFIX_RANGE, Operation.STARTS_WITH, "ca")).isTrue();
		assertThat(probe(range, Variant.PREFIX_RANGE, Operation.STARTS_WITH, "cb")).isFalse();
		assertThat(probe(range, Variant.PREFIX_RANGE, Operation.EQUALS, "ca")).isFalse();
		assertThat(probe(range, Variant.PREFIX_RANGE, Operation.CONTAINS, "a")).isTrue();
		for (Variant variant : List.of(Variant.MAX_LENGTH, Variant.PREFIX_RANGE)) {
			byte[] header = PageTextPrototypeSummary.build(variant, List.of("\u20ac", "a"));
			for (Operation operation : Operation.values()) {
				assertThat(probe(header, variant, operation, "\ud83d\ude00")).isFalse();
			}
			ByteBuffer.wrap(header).order(ByteOrder.LITTLE_ENDIAN).putInt(4, -1);
			assertThat(probe(header, variant, Operation.EQUALS, "very long absent value")).isTrue();
		}
	}

	@Test
	void specializedSignaturesConstrainOnlyTheirSupportedOperations() {
		for (Variant variant : List.of(Variant.EQ_HASH256, Variant.EQ_HASH1024, Variant.EQ_HASH4096,
				Variant.EQ1_HASH1024)) {
			byte[] header = PageTextPrototypeSummary.build(variant, List.of("abcdefghi-one", "", "\u20ac"));
			for (String needle : List.of("abcdefghi-one", "", "\u20ac")) {
				assertThat(probe(header, variant, Operation.EQUALS, needle)).isTrue();
			}
			assertThat(probe(header, variant, Operation.EQUALS, "abcdefghi-two")).isFalse();
			assertThat(probe(header, variant, Operation.CONTAINS, "absent")).isTrue();
			assertThat(probe(header, variant, Operation.STARTS_WITH, "absent")).isTrue();
		}
		byte[] oneHash = PageTextPrototypeSummary.build(Variant.EQ1_HASH1024, List.of("label"));
		byte[] threeHashes = PageTextPrototypeSummary.build(Variant.EQ_HASH1024, List.of("label"));
		assertThat(PageTextPrototypeSummary.occupiedBits(oneHash, Variant.EQ1_HASH1024)).isEqualTo(1);
		assertThat(PageTextPrototypeSummary.occupiedBits(threeHashes, Variant.EQ_HASH1024)).isEqualTo(3);
		for (int i = PageTextPrototypeSummary.FRAMING_BYTES; i < oneHash.length; i++) {
			assertThat(oneHash[i] & threeHashes[i]).isEqualTo((int) oneHash[i]);
		}
		for (Variant variant : List.of(Variant.PREFIX_GRAM256, Variant.PREFIX_GRAM1024)) {
			byte[] header = PageTextPrototypeSummary.build(variant, List.of("prefix needle"));
			assertThat(probe(header, variant, Operation.STARTS_WITH, "pre")).isTrue();
			assertThat(probe(header, variant, Operation.STARTS_WITH, "prefix")).isTrue();
			assertThat(probe(header, variant, Operation.STARTS_WITH, "xy")).isTrue();
			assertThat(probe(header, variant, Operation.STARTS_WITH, "needle")).isFalse();
			assertThat(probe(header, variant, Operation.EQUALS, "prefix needle")).isTrue();
			assertThat(probe(header, variant, Operation.CONTAINS, "needle")).isTrue();
			assertThat(probe(header, variant, Operation.CONTAINS, "absent")).isTrue();
		}
	}

	@Test
	void emptyPagesAndEmptyLiteralsHaveDifferentSemantics() {
		for (Variant variant : Variant.values()) {
			byte[] emptyPage = PageTextPrototypeSummary.build(variant, List.of());
			byte[] emptyLiteral = PageTextPrototypeSummary.build(variant, List.of(""));
			for (Operation operation : Operation.values()) {
				assertThat(probe(emptyPage, variant, operation, "")).isEqualTo(variant == Variant.NONE);
				assertThat(probe(emptyLiteral, variant, operation, "")).isTrue();
			}
		}
		assertThat(PageTextPrototypeSummary.exactGramMayMatch(List.of(), "")).isFalse();
		assertThat(PageTextPrototypeSummary.exactGramMayMatch(List.of(""), "")).isTrue();
	}

	@Test
	void literalSummaryAggregationRejectsUnknownLayoutsAndRetainsSaturatedSignatures() {
		List<byte[]> invalid = new ArrayList<>();
		invalid.add(null);
		invalid.add(new byte[LiteralTextSummary.BYTES - 1]);
		byte[] wrongVersion = LiteralTextSummary.create("label", Locale.ROOT);
		wrongVersion[2]++;
		invalid.add(wrongVersion);
		for (byte[] summary : invalid) {
			byte[] page = PageTextPrototypeSummary.buildGram256FromLiteralSummaries(Arrays.asList(summary));
			assertThat(probe(page, Variant.GRAM256, Operation.CONTAINS, "long absent label")).isTrue();
		}
		Random random = new Random(0x51a7eL);
		StringBuilder builder = new StringBuilder(32_768);
		for (int i = 0; i < 32_000; i++) {
			builder.append((char) (' ' + random.nextInt(95)));
		}
		builder.append("FINAL-\u03a3-NEEDLE-\ud83d\ude00");
		String label = builder.toString().toLowerCase(Locale.ROOT);
		byte[] saturated = PageTextPrototypeSummary.buildGram256FromLiteralSummaries(
				List.of(LiteralTextSummary.create(label, Locale.ROOT)));
		assertThat(saturated).isEqualTo(PageTextPrototypeSummary.build(Variant.GRAM256, List.of(label)));
		assertThat(PageTextPrototypeSummary.occupiedBits(saturated, Variant.GRAM256)).isEqualTo(256);
		assertThat(probe(saturated, Variant.GRAM256, Operation.CONTAINS, "needle-\ud83d\ude00")).isTrue();
	}

	@Test
	void randomizedUnicodePagesNeverRejectAnExactMatch() {
		Random random = new Random(0x7e87_5eedL);
		int[] alphabet = { 'A', 'a', 'I', 'i', '\u0130', '\u0131', '\u03a3', '\u03c2', '\u0301', '\u0307',
				' ', '0', '-', '\u0000', '\u00e9', '\u20ac', 0x1f600, 0x10400 };
		for (int sample = 0; sample < 40; sample++) {
			Locale locale = sample % 2 == 0 ? Locale.ROOT : Locale.forLanguageTag("tr");
			List<String> labels = new ArrayList<>();
			for (int n = 0, count = 1 + random.nextInt(12); n < count; n++) {
				StringBuilder builder = new StringBuilder();
				for (int i = 0, length = random.nextInt(13); i < length; i++) {
					builder.appendCodePoint(alphabet[random.nextInt(alphabet.length)]);
				}
				String persisted = new String(builder.toString().getBytes(StandardCharsets.UTF_8),
						StandardCharsets.UTF_8);
				labels.add(persisted.toLowerCase(locale));
			}
			for (Variant variant : Variant.values()) {
				byte[] page = PageTextPrototypeSummary.build(variant, labels);
				for (String label : labels) {
					assertThat(probe(page, variant, Operation.EQUALS, label)).as("%s %s", variant, sample).isTrue();
					assertEverySubstringSurvives(page, variant, label);
				}
			}
		}
	}

	private static void assertEverySubstringSurvives(byte[] page, Variant variant, String label) {
		for (int from = 0; from <= label.length(); from++) {
			for (int to = from; to <= label.length(); to++) {
				String needle = label.substring(from, to);
				assertThat(probe(page, variant, Operation.CONTAINS, needle))
						.as("%s contains [%s,%s) of %s", variant, from, to, label)
						.isTrue();
				if (from == 0) {
					assertThat(probe(page, variant, Operation.STARTS_WITH, needle))
							.as("%s prefix %s of %s", variant, to, label)
							.isTrue();
				}
			}
		}
	}

	private static boolean probe(byte[] header, Variant variant, Operation operation, String needle) {
		return PageTextPrototypeSummary.mayMatch(header, PageTextPrototypeSummary.prepare(variant, operation, needle));
	}
